# Surah Hud (chapter 11) — part 6: ayat 51-60 (IDs 1524-1533)
SURAH = 11

ENTRIES = {
1524: (
"اے میری قوم — میں — اس — پر — تم — سے — کوئی بدلہ — نہیں مانگتا — میرا — بدلہ — صرف — اس — کے — ذمے ہے — جس — نے — مجھے — پیدا — کیا — کیا — تم — نہیں سمجھتے",
"""۱۔ ہودؑ — پیغام رسالت — بلا — بدلہ۔
۲۔ ’’يَا قَوْمِ لَا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِنْ أَجْرِيَ إِلَّا عَلَى الَّذِي فَطَرَنِي أَفَلَا تَعْقِلُونَ‘‘ — اے میری قوم — میں — اس — پر — تم — سے — کوئی بدلہ — نہیں مانگتا — میرا — بدلہ — صرف — اس — کے — ذمے ہے — جس — نے — مجھے — پیدا — کیا — کیا — تم — نہیں سمجھتے — یعنی میں — تم سے — کوئی بدلہ نہیں مانگتا — میرا بدلہ — صرف اس — کے ذمے ہے — جس نے مجھے پیدا — کیا — کیا تم — نہیں سمجھتے۔
۳۔ عملی سبق: حق کا پیغام — بلا — معاوضہ — پہنچائیں۔"""
),
1525: (
"اور — اے میری قوم — اپنے رب سے — استغفار — کرو — پھر — اس کی طرف — توبہ — کرو — وہ — تم — پر — بارش — برسنے والی — بھی — بھیجے گا — اور — تمہاری — قوت — میں — قوت — بڑھائے گا — اور — تم — مجرم — ہو کر — منہ نہ موڑو",
"""۱۔ استغفار اور توبہ — آسمانی برکت — اور طاقت کا ذریعہ۔
۲۔ ’’وَيَا قَوْمِ اسْتَغْفِرُوا رَبَّكُمْ ثُمَّ تُوبُوا إِلَيْهِ يُرْسِلِ السَّمَاءَ عَلَيْكُم مِّدْرَارًا وَيَزِدْكُمْ قُوَّۃً إِلَىٰ قُوَّتِكُمْ وَلَا تَتَوَلَّوْا مُجْرِمِينَ‘‘ — اور — اے میری قوم — اپنے رب سے — استغفار — کرو — پھر — اس کی طرف — توبہ — کرو — وہ — تم — پر — بارش — برسنے والی — بھی — بھیجے گا — اور — تمہاری — قوت — میں — قوت — بڑھائے گا — اور — تم — مجرم — ہو کر — منہ نہ موڑو — یعنی اے قوم — اپنے رب سے استغفار کرو — اور اس کی طرف — توبہ کرو — وہ تم پر — لگا تار بارش — بھیجے گا — اور تمہاری — قوت — میں اضافہ کرے گا — اور تم — مجرم — ہو کر منہ — نہ موڑو۔
۳۔ عملی سبق: استغفار — بے برکتی — کو — برکت — میں — بدل دیتا ہے۔"""
),
1526: (
"انہوں نے — کہا — اے ہودؑ — تم — ہمارے پاس — کوئی — دلیل — نہیں لائے — اور — ہم — تمہارے — کہنے پر — اپنے — معبودوں — کو — چھوڑنے والے — نہیں — اور — ہم — تم — پر — ایمان — نہیں لانے والے",
"""۱۔ قوم — ہودؑ کے دلائل — کو — مسترد — کرتی ہے۔
۲۔ ’’قَالُوا يَا هُودُ مَا جِئْتَنَا بِبَيِّنَۃٍ وَمَا نَحْنُ بِتَارِكِي آلِهَتِنَا عَن قَوْلِكَ وَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ‘‘ — انہوں نے — کہا — اے ہودؑ — تم — ہمارے پاس — کوئی — دلیل — نہیں لائے — اور — ہم — تمہارے — کہنے پر — اپنے — معبودوں — کو — چھوڑنے والے — نہیں — اور — ہم — تم — پر — ایمان — نہیں لانے والے — یعنی انہوں نے کہا — اے ہودؑ — تمہاری کوئی دلیل — نہیں — اور ہم — تمہارے — کہنے پر — اپنے معبودوں — کو — نہیں — چھوڑ سکتے — اور ہم — تم — پر ایمان — نہیں لائیں گے۔
۳۔ عملی سبق: ضد — دلیل — کو — بھی — رد کر دیتی ہے؛ تعصب — سے — بچو۔"""
),
1527: (
"ہم — صرف یہی کہتے ہیں — کہ — ہمیں — کچھ — معبودوں نے — برائی پہنچائی ہے — انہوں نے — کہا — میں — اللہ — کو — گواہ بناتا ہوں — اور — تم — سب گواہ — رہو — کہ — میں — اس — چیز — سے بری ہوں — جس سے — تم — شرک کرتے ہو",
"""۱۔ قوم — معبودوں کی طرف — سے — برائی کا دعویٰ — ہودؑ — براءت — کا اعلان۔
۲۔ ’’إِن نَّقُولُ إِلَّا اعْتَرَاكَ بَعْضُ آلِهَتِنَا بِسُوءٍ قَالَ إِنِّي أُشْهِدُ اللَّهَ وَاشْهَدُوا أَنِّي بَرِيءٌ مِّمَّا تُشْرِكُونَ‘‘ — ہم — صرف یہی کہتے ہیں — کہ — ہمیں — کچھ — معبودوں نے — برائی پہنچائی ہے — انہوں نے — کہا — میں — اللہ — کو — گواہ بناتا ہوں — اور — تم — سب گواہ — رہو — کہ — میں — اس — چیز — سے بری ہوں — جس سے — تم — شرک کرتے ہو — یعنی انہوں نے کہا — اے ہودؑ — ہمارے — معبودوں نے — تمہیں — برائی پہنچائی ہے — ہودؑ — نے کہا — میں — اللہ — کو — گواہ بناتا ہوں — اور تم سب گواہ رہو — کہ میں — تمہارے — شرک — سے بری ہوں۔
۳۔ عملی سبق: شرک سے — کھلے — الفاظ میں — براءت کا اعلان — کرو۔"""
),
1528: (
"اس — کے — علاوہ — میں — بجز اس کے جو — اللہ — ہے — کوئی اقرار — نہیں کرتا — پس — تم — سب مل کر — مجھ سے چال — چلو — پھر — مجھے — مہلت — نہ دو",
"""۱۔ ہودؑ — قوم کو چیلنج — دیتے ہیں — تمہارے شریک — مجھے کچھ نہیں کر سکتے۔
۲۔ ’’مِن دُونِهِ فَكِيدُونِي جَمِيعًا ثُمَّ لَا تُنظِرُونِ‘‘ — اس — کے — علاوہ — میں — بجز اس کے جو — اللہ — ہے — کوئی اقرار — نہیں کرتا — پس — تم — سب مل کر — مجھ سے چال — چلو — پھر — مجھے — مہلت — نہ دو — یعنی اللہ کے علاوہ — کسی کو میں تسلیم نہیں کرتا — تم — سب مل کر — مجھ سے چال — چلو — اور پھر — مجھے — مہلت — نہ دو۔
۳۔ عملی سبق: حق والے کو — اللہ کی مدد — پر — یقین ہوتا ہے؛ دشمن کچھ نہیں کر سکتا۔"""
),
1529: (
"بے شک — میں — اس — اللہ — پر — بھروسہ رکھتا ہوں — جو — میرا اور — تمہارا — رب ہے — کوئی — جاندار — ایسا — نہیں — جس کی — پیشانی — اس کے ہاتھ — میں — نہ ہو — بے شک — میرا رب — سیدھے راستے — پر ہے",
"""۱۔ ہودؑ — اللہ پر کامل توکل — پیشانی اللہ کے ہاتھ میں۔
۲۔ ’’إِنِّي تَوَكَّلْتُ عَلَى اللَّهِ رَبِّي وَرَبِّكُم مَّا مِن دَابَّۃٍ إِلَّا هُوَ آخِذٌ بِنَاصِيَتِهَا إِنَّ رَبِّي عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ‘‘ — بے شک — میں — اس — اللہ — پر — بھروسہ رکھتا ہوں — جو — میرا اور — تمہارا — رب ہے — کوئی — جاندار — ایسا — نہیں — جس کی — پیشانی — اس کے ہاتھ — میں — نہ ہو — بے شک — میرا رب — سیدھے راستے — پر ہے — یعنی میں — اس اللہ پر بھروسہ رکھتا ہوں — جو میرا اور تمہارا — رب ہے؛ کوئی — جاندار — ایسا نہیں — جس کی — پیشانی — اس کے ہاتھ میں نہ ہو — بے شک — میرا رب — سیدھے راستے پر — ہے۔
۳۔ عملی سبق: پیشانی اللہ کے ہاتھ میں — ہے — اس سے — بڑھ کر — کوئی طاقت نہیں۔"""
),
1530: (
"پس — اگر — وہ — منہ موڑ لیں — تو — میں — تمہارے پاس — وہ — پہنچا دیا جس — کے لیے — مجھے — بھیجا گیا — اور — میرا رب — تمہارے بعد — دوسری قوم — کو — خلیفہ — بنا دے گا — اور — تم — اسے — کچھ — نقصان نہیں پہنچا سکتے — بے شک — میرا رب — ہر چیز — کی — حفاظت کرنے والا — ہے",
"""۱۔ ہودؑ — کی ذمہ داری — پیغام پہنچانا؛ نتائج — اللہ کے ہاتھ میں۔
۲۔ ’’فَإِن تَوَلَّوْا فَقَدْ أَبْلَغْتُكُم مَّا أُرْسِلْتُ بِهِ إِلَيْكُمْ وَيَسْتَخْلِفُ رَبِّي قَوْمًا غَيْرَكُمْ وَلَا تَضُرُّونَهُ شَيْئًا إِنَّ رَبِّي عَلَىٰ كُلِّ شَيْءٍ حَفِيظٌ‘‘ — پس — اگر — وہ — منہ موڑ لیں — تو — میں — تمہارے پاس — وہ — پہنچا دیا جس — کے لیے — مجھے — بھیجا گیا — اور — میرا رب — تمہارے بعد — دوسری قوم — کو — خلیفہ — بنا دے گا — اور — تم — اسے — کچھ — نقصان نہیں پہنچا سکتے — بے شک — میرا رب — ہر چیز — کی — حفاظت کرنے والا — ہے — یعنی اگر — وہ منہ موڑ لیں — تو — میں — تمہیں وہ پیغام پہنچا دیا — جس کے لیے مجھے بھیجا — گیا تھا — میرا رب — تمہارے — بعد دوسری قوم — کو خلیفہ — بنا دے گا — اور تم اسے — کچھ — نقصان — نہیں پہنچا سکتے — بے شک — میرا رب — ہر چیز کا محافظ — ہے۔
۳۔ عملی سبق: پیغام — پہنچانا آپ کی ذمہ داری ہے؛ نتیجہ — اللہ — پر چھوڑو۔"""
),
1531: (
"اور — جب — ہمارا حکم — آیا — ہم — نے — ہودؑ — کو — اور — اس — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت سے — نجات دی — اور — ہم — نے — انہیں — ایک — سخت — عذاب — سے بچایا",
"""۱۔ ہودؑ اور مؤمنین — نجات پائے؛ سخت عذاب — عاد — پر۔
۲۔ ’’وَلَمَّا جَاءَ أَمْرُنَا نَجَّيْنَا هُودًا وَالَّذِينَ آمَنُوا مَعَهُ بِرَحْمَۃٍ مِّنَّا وَنَجَّيْنَاهُم مِّنْ عَذَابٍ غَلِيظٍ‘‘ — اور — جب — ہمارا حکم — آیا — ہم — نے — ہودؑ — کو — اور — اس — کے ساتھ ایمان لانے والوں — کو — اپنی رحمت سے — نجات دی — اور — ہم — نے — انہیں — ایک — سخت — عذاب — سے بچایا — یعنی جب ہماراحکم — آیا — ہم نے ہودؑ — اور — اس کے ساتھیوں — کو — اپنی رحمت سے — نجات — دی؛ اور — ہم نے انہیں سخت عذاب — سے بچا لیا۔
۳۔ عملی سبق: ایمان — سخت عذاب سے — نجات — کا ذریعہ ہے۔"""
),
1532: (
"اور — یہ — عاد — ہے — انہوں نے — اپنے رب — کی آیات — کا انکار کیا — اور — اس — کے رسولوں — کی نافرمانی کی — اور — ہر سرکش — مخالف — کی بات — پیروی کی",
"""۱۔ عاد قوم — کا — جرم: آیات کا انکار اور سرکشوں کی پیروی۔
۲۔ ’’وَتِلْكَ عَادٌ جَحَدُوا بِآيَاتِ رَبِّهِمْ وَعَصَوْا رُسُلَهُ وَاتَّبَعُوا أَمْرَ كُلِّ جَبَّارٍ عَنِيدٍ‘‘ — اور — یہ — عاد — ہے — انہوں نے — اپنے رب — کی آیات — کا انکار کیا — اور — اس — کے رسولوں — کی نافرمانی کی — اور — ہر سرکش — مخالف — کی بات — پیروی کی — یعنی یہ عاد ہے — انہوں نے اپنے رب کی آیات کا — انکار — کیا — اور — اس کے رسولوں کی نافرمانی — کی — اور ہر سرکش مخالف — کی اطاعت — کی۔
۳۔ عملی سبق: سرکشی — کی اطاعت — ہلاکت — کی دلیل ہے۔"""
),
1533: (
"اور — اس دنیا میں — ان — کے پیچھے — لعنت — چلائی گئی — اور — قیامت کے دن — بھی — سنو — عاد — نے — اپنے رب کا — انکار — کیا — سنو — ہودؑ — کی قوم — عاد — کے لیے — ہلاکت — ہے",
"""۱۔ عاد — کے لیے دنیا اور آخرت — دونوں میں لعنت۔
۲۔ ’’وَأُتْبِعُوا فِي هَٰذِهِ الدُّنْيَا لَعْنَۃً وَيَوْمَ الْقِيَامَۃِ أَلَا إِنَّ عَادًا كَفَرُوا رَبَّهُمْ أَلَا بُعْدًا لِّعَادٍ قَوْمِ هُودٍ‘‘ — اور — اس دنیا میں — ان — کے پیچھے — لعنت — چلائی گئی — اور — قیامت کے دن — بھی — سنو — عاد — نے — اپنے رب کا — انکار — کیا — سنو — ہودؑ — کی قوم — عاد — کے لیے — ہلاکت — ہے — یعنی عاد — کے پیچھے — اس دنیا میں لعنت — چلائی گئی — اور قیامت کے دن — بھی؛ سنو — عاد — نے اپنے رب — کا انکار کیا — سنو ہلاکت ہے — عاد قومِ ہودؑ — کو۔
۳۔ عملی سبق: رب کے انکار — کا نتیجہ — دنیا و آخرت — دونوں میں ذلت ہے۔"""
),
}
